import{_ as a,o as r,c as e,ai as o}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI","description":"","frontmatter":{"date":"2026-10-26T00:00:00.000Z","title":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI","summary":"社区与 @grok 回复确认：连接应用列表里已有飞书插件，授权后可读写信、文档。步骤来自公开说明，我们未走通授权；新插件更偏 Lark，部分飞书账号可能授权不顺。","category":"新插件","tags":["插件","飞书","Lark","连接应用"],"sources":[{"url":"https://x.com/KinGao476942/status/2114228969465889003","author":"@KinGao476942","platform":"X"},{"url":"https://x.com/fangqizhou/status/2114312794699149749","author":"@fangqizhou","platform":"X"},{"url":"https://x.com/grok/status/2114361747599405534","author":"@grok","platform":"X"}],"updates":[{"link":"/basics/connectors-plugins","title":"连接器与插件：补充飞书 / Lark 一节"},{"link":"/resources/?tab=plugins","title":"资源导航 · 插件与连接器：新增飞书插件"}],"wordCount":478,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"社区与 @grok 回复确认：连接应用列表里已有飞书插件，授权后可读写信、文档。步骤来自公开说明，我们未走通授权；新插件更偏 Lark，部分飞书账号可能授权不顺。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-26-feishu-plugin"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-26-feishu-plugin-0b4bce8157.png"}],["meta",{"property":"og:image:alt","content":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"社区与 @grok 回复确认：连接应用列表里已有飞书插件，授权后可读写信、文档。步骤来自公开说明，我们未走通授权；新插件更偏 Lark，部分飞书账号可能授权不顺。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-26-feishu-plugin-0b4bce8157.png"}],["meta",{"name":"twitter:image:alt","content":"Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-26-feishu-plugin"}]]},"headers":[],"relativePath":"daily/2026-10-26-feishu-plugin.md","filePath":"daily/2026-10-26-feishu-plugin.md","lastUpdated":1792945242000}'),n={name:"daily/2026-10-26-feishu-plugin.md"};function i(s,t,l,g,p,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="grok-bot-飞书-lark-插件-在「连接应用」里直接授权-少配一遍-cli" tabindex="-1">Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI <a class="header-anchor" href="#grok-bot-飞书-lark-插件-在「连接应用」里直接授权-少配一遍-cli" aria-label="Permalink to &quot;Grok Bot 飞书 / Lark 插件：在「连接应用」里直接授权，少配一遍 CLI&quot;">​</a></h1><p>以前让 Grok Bot 读写飞书，常见做法是每个 Bot 单独开一个飞书应用，再走 CLI。2026-10-25 起，社区多人确认：<strong>「连接应用」里已经能搜到飞书插件</strong>，弹窗授权后可读写文档和消息，不用再为每个 Bot 重配一套 CLI 应用。</p><p>依据（公开帖，<strong>不是</strong>我们实测授权）：</p><ul><li><a href="https://x.com/KinGao476942/status/2114228969465889003" target="_blank" rel="noopener noreferrer">@KinGao476942</a>（约 1.8 万浏览、51 赞、47 收藏）：提示词「请你弹窗、帮我连接到我的飞书插件应用」，再按指引授权。</li><li><a href="https://x.com/fangqizhou/status/2114312794699149749" target="_blank" rel="noopener noreferrer">@fangqizhou</a>：对比「以前靠飞书 CLI、现在装插件按指引授权」。</li><li><a href="https://x.com/grok/status/2114361747599405534" target="_blank" rel="noopener noreferrer">@grok</a>：确认可在「连接应用」搜索添加；能读写文档和消息；<strong>若账号授权不顺，可改用 CLI 或试 Lark 国际版</strong>。</li></ul><h2 id="怎么连-社区-grok-说法" tabindex="-1">怎么连（社区 / @grok 说法） <a class="header-anchor" href="#怎么连-社区-grok-说法" aria-label="Permalink to &quot;怎么连（社区 / @grok 说法）&quot;">​</a></h2><div class="steps"><ol><li>在对话里让 Bot「请帮我连接到飞书插件」，或打开侧边栏 <strong>连接应用</strong>。</li><li>搜索「飞书」或 Feishu / Lark，按弹窗完成官方授权。</li><li>回到对话，让 Bot 列一下已连接应用，再试读一篇你有权限的文档。</li></ol></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我连接到飞书插件，授权完成后告诉我现在能读写哪些飞书能力。</span></span></code></pre></div><h2 id="注意-务必读" tabindex="-1">注意（务必读） <a class="header-anchor" href="#注意-务必读" aria-label="Permalink to &quot;注意（务必读）&quot;">​</a></h2><ul><li><strong>我们未能在本环境完成飞书 / Lark 授权</strong>，因此本页<strong>不写「WANGXXXL 实测」</strong>；能力边界以连接应用内实际列表和授权结果为准。</li><li>新插件目前更偏 <strong>Lark（国际版）</strong> 一侧；飞书账号与 Lark 账号、授权链路<strong>通常不通用</strong>。授权失败时，<a href="https://x.com/grok/status/2114355684338696433" target="_blank" rel="noopener noreferrer">@grok</a> 建议改用飞书 CLI，或改试 Lark 国际版。</li><li>连接器账号级共享：连一次，你名下多个 Bot 可能都能用——只连需要的应用，写操作保持「先问我」。详见 <a href="/basics/connectors-plugins">连接器与插件</a>。</li></ul><p>资料入口：<a href="https://x.com/KinGao476942/status/2114228969465889003" target="_blank" rel="noopener noreferrer">Kin 的说明帖</a> · <a href="/basics/connectors-plugins">连接器与插件</a></p>',10)])])}const k=a(n,[["render",i]]);export{h as __pageData,k as default};
